def page(
    pdf_page: int,
    reference: str,
    category: str,
    section: str,
    text: str,
    terms: list[str],
    *,
    source_url: str | None = None,
    source_kind: str | None = None,
    source_date: str | None = None,
) -> dict[str, object]:
    item: dict[str, object] = {
        "pdfPage": pdf_page,
        "referenceLabel": reference,
        "category": category,
        "searchTerms": terms,
        "section": section,
        "text": text,
    }
    if source_url:
        item["sourceUrl"] = source_url
    if source_kind:
        item["sourceKind"] = source_kind
    if source_date is not None:
        item["sourceDate"] = source_date
    return item


def write_source(filename: str, payload: dict[str, object]) -> None:
    payload["chunkCount"] = len(payload["pages"])
    path = DATA_DIR / filename
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"Wrote {payload['chunkCount']} chunks to {path}")


